import overrides from '../../tokens/overrides.json';
import product from '../../tokens/product.json';
import source from '../../tokens/rocketwave.tokens.json';

/*
 * Turns the token files in packages/ui/tokens into CSS:
 * - tokens.css: CSS variables (--rw-*) for light and dark themes
 * - theme.css: the Tailwind theme, which exposes only these tokens as utilities
 * Run `pnpm --filter @rwos/ui tokens:build` after changing a token file; a test fails if the
 * generated files are out of date.
 */

export type Theme = 'light' | 'dark';

export interface ColorToken {
  name: string;
  light: string;
  dark: string;
  usage: string;
  /** Set when an accessibility override changed the design system value. */
  overridden?: Partial<Record<Theme, { was: string; reason: string }>>;
}

export interface TypeStyle {
  name: string;
  family: 'sans' | 'display' | 'mono';
  fontSize: string;
  lineHeight: string;
  fontWeight: number;
  letterSpacing?: string;
}

export interface TokenModel {
  colors: ColorToken[];
  families: Record<'sans' | 'display' | 'mono', string>;
  typeStyles: TypeStyle[];
  spacing: { name: string; value: string }[];
  radius: { name: string; value: string }[];
  shadows: { name: string; light: string; dark: string }[];
  sizes: { name: string; value: string }[];
  containers: { name: string; value: string }[];
  logo: { light: Record<string, string>; dark: Record<string, string>; white: string };
}

const HEADER =
  '/* Rocket Wave design tokens. GENERATED by packages/ui/src/tokens/build.ts from packages/ui/tokens/*.json: do not edit by hand. */';

type ColorOverride = { light?: string; dark?: string; was: string; reason: string };

export function resolveTokens(): TokenModel {
  const colorOverrides = overrides.color as Record<string, ColorOverride>;

  const colors: ColorToken[] = source.color.tokens.map((token) => {
    const override = colorOverrides[token.name];
    const resolved: ColorToken = {
      name: token.name,
      light: override?.light ?? token.value.light,
      dark: override?.dark ?? token.value.dark,
      usage: token.usage,
    };
    if (override) {
      resolved.overridden = {};
      if (override.light)
        resolved.overridden.light = { was: token.value.light, reason: override.reason };
      if (override.dark)
        resolved.overridden.dark = { was: token.value.dark, reason: override.reason };
    }
    return resolved;
  });

  const byName = new Map(colors.map((color) => [color.name, color]));
  for (const [name, alias] of Object.entries(overrides.aliases)) {
    const light = byName.get(alias.light);
    const dark = byName.get(alias.dark);
    if (!light || !dark) throw new Error(`Alias ${name} points at a missing colour token`);
    colors.push({ name, light: light.light, dark: dark.dark, usage: alias.usage });
  }

  const groupFamily = (group: { family: string }) => group.family as TypeStyle['family'];
  const typeStyles: TypeStyle[] = source.type.groups.flatMap((group) =>
    group.styles.map((style) => ({
      name: style.name,
      family: groupFamily(group),
      fontSize: style.fontSize,
      lineHeight: style.lineHeight,
      fontWeight: style.fontWeight,
      ...('letterSpacing' in style ? { letterSpacing: style.letterSpacing } : {}),
    })),
  );

  const families = {
    sans: `"${product.fontFaces.sans}", ${source.type.families.sans}`,
    display: `"${product.fontFaces.display}", ${source.type.families.display}`,
    mono: `"${product.fontFaces.mono}", ${source.type.families.mono}`,
  };

  return {
    colors,
    families,
    typeStyles,
    spacing: source.spacing.tokens.map(({ name, value }) => ({ name, value })),
    radius: source.radius.tokens.map(({ name, value }) => ({ name, value })),
    shadows: source.shadow.tokens.map(({ name, value }) => ({
      name,
      light: value,
      // Design system: cards use shadow-sm in the light theme only; dark uses the border.
      dark: name === 'shadow-sm' ? 'none' : value,
    })),
    sizes: Object.entries(product.size).map(([name, { value }]) => ({ name, value })),
    containers: Object.entries(product.container).map(([name, { value }]) => ({ name, value })),
    logo: product.logo,
  };
}

function themeVariables(model: TokenModel, theme: Theme): string[] {
  return [
    ...model.colors.map((color) => `  --rw-color-${color.name}: ${color[theme]};`),
    ...model.shadows.map((shadow) => `  --rw-${shadow.name}: ${shadow[theme]};`),
    ...Object.entries(model.logo[theme]).map(([part, value]) => `  --rw-logo-${part}: ${value};`),
  ];
}

export function renderTokensCss(model: TokenModel): string {
  const shared = [
    `  --rw-font-sans: ${model.families.sans};`,
    `  --rw-font-display: ${model.families.display};`,
    `  --rw-font-mono: ${model.families.mono};`,
    ...model.spacing.map((space) => `  --rw-${space.name}: ${space.value};`),
    ...model.radius.map((radius) => `  --rw-${radius.name}: ${radius.value};`),
    `  --rw-logo-white: ${model.logo.white};`,
  ];
  const light = themeVariables(model, 'light');
  const dark = themeVariables(model, 'dark');

  return [
    HEADER,
    '',
    '/* Light is the default; data-theme on <html> forces a theme; otherwise the system setting wins. */',
    ':root {',
    ...shared,
    '}',
    '',
    ':root,',
    ':root[data-theme="light"] {',
    '  color-scheme: light;',
    ...light,
    '}',
    '',
    ':root[data-theme="dark"] {',
    '  color-scheme: dark;',
    ...dark,
    '}',
    '',
    '@media (prefers-color-scheme: dark) {',
    '  :root:not([data-theme="light"]) {',
    '    color-scheme: dark;',
    ...dark.map((line) => `  ${line}`),
    '  }',
    '}',
    '',
  ].join('\n');
}

export function renderThemeCss(model: TokenModel): string {
  const typeLines = model.typeStyles.flatMap((style) => [
    `  --text-${style.name}: ${style.fontSize};`,
    `  --text-${style.name}--line-height: ${style.lineHeight};`,
    `  --text-${style.name}--font-weight: ${style.fontWeight};`,
    ...(style.letterSpacing
      ? [`  --text-${style.name}--letter-spacing: ${style.letterSpacing};`]
      : []),
  ]);

  return [
    HEADER,
    '',
    "/* Remove Tailwind's default palette, fonts, type scale, radii, shadows and spacing scale, so only",
    '   Rocket Wave tokens exist as utilities (CLAUDE.md: only design tokens, no raw values). */',
    '@theme {',
    '  --color-*: initial;',
    '  --font-*: initial;',
    '  --text-*: initial;',
    '  --radius-*: initial;',
    '  --shadow-*: initial;',
    '  --spacing: initial;',
    '  --spacing-*: initial;',
    '  --container-*: initial;',
    '',
    ...typeLines,
    '}',
    '',
    '/* Theme-dependent values point at the --rw-* variables, so utilities switch with the theme. */',
    '@theme inline {',
    ...model.colors.map((color) => `  --color-${color.name}: var(--rw-color-${color.name});`),
    '',
    '  --font-sans: var(--rw-font-sans);',
    '  --font-display: var(--rw-font-display);',
    '  --font-mono: var(--rw-font-mono);',
    '',
    '  --spacing-0: 0px;',
    ...model.spacing.map(
      (space) => `  --spacing-${space.name.replace('space-', '')}: var(--rw-${space.name});`,
    ),
    ...model.sizes.map((size) => `  --spacing-${size.name}: ${size.value};`),
    '',
    ...model.containers.map((container) => `  --container-${container.name}: ${container.value};`),
    '',
    ...model.radius.map((radius) => `  --${radius.name}: var(--rw-${radius.name});`),
    '',
    ...model.shadows.map((shadow) => `  --${shadow.name}: var(--rw-${shadow.name});`),
    '}',
    '',
  ].join('\n');
}
